import React, { useState } from 'react';
import './Login101.css'; // Make sure to import the CSS file

const Login101 = () => {
    const [name, setName] = useState('');
    const [age, setAge] = useState('');
    const [responseMessage, setResponseMessage] = useState('');

    const handleSubmit = (event) => {
        event.preventDefault();
        setResponseMessage(`Submitted: Name - ${name}, Age - ${age}`);
        setName('');
        setAge('');
    };

    return (
        <div className="form-container">
            <h2>Form Submission</h2>
            <form id="dataForm" onSubmit={handleSubmit}>
                <div className="form-group">
                    <label htmlFor="name">Name:</label>
                    <input
                        type="text"
                        id="name"
                        name="name"
                        placeholder="Name"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        required
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="age">Age:</label>
                    <input
                        type="number"
                        id="age"
                        name="age"
                        placeholder="Age"
                        value={age}
                        onChange={(e) => setAge(e.target.value)}
                        required
                    />
                </div>
                <button type="submit" className="submit-btn">Submit</button>
            </form>
            {responseMessage && <div id="responseMessage" className="response-message">{responseMessage}</div>}
        </div>
    );
};

export default Login101;
